import React, { Component } from 'react';
import {
  View,
  Text,
  Image,
  StyleSheet,
  Dimensions,
  ScrollView,
  TouchableNativeFeedback,
  Platform,
  Alert,
  FlatList,
  BackHandler
} from 'react-native';
import Modal from 'react-native-modal';
import {StackActions, NavigationActions} from 'react-navigation';
import {MaterialIndicator} from 'react-native-indicators';
import * as Progress from 'react-native-progress';
import RenderQuestions from '../renderQuestions';
import axios from "axios";

const screen = Dimensions.get('window');
  vh = screen.height / 100;
  vw = screen.width / 100;

class viewTest extends Component {


  static navigationOptions = ({ navigation }) => ({
    header: null
  })

  constructor() {
    super();
    this.state = {
      timer: 600,
      ActiveSlide: 0,
      startTime: new Date(),
      blocks: [],
      questionContainerHeight: 0,
      questionIndex: 0,
      n_questions: 0,
      attempted: false,
      num_attempted: 0,
      modalTimeup: false,
      modalPerformance: false,
      totalScore: 0,
      currentIndex: -1,
      correctAnswer: -1,
      loadingCompleted: false,
      testCardShow: false,
      goal: [],
      subjects: [],
      activeGoal: 0,
      activeSubject: 0,
      isReady: false,
      sections: [],
      selectedSection: 0,
      loading: false,
      language: 'en',
      showReviewModal: false,
      showSubmitModal: false
    }
    this.handleBackButton = this.handleBackButton.bind(this);
  }

  handleBackButton() {
    return false;
  }


  componentWillUnmount() {
    BackHandler.removeEventListener('hardwareBackPress', this.handleBackButton);
  }

  async componentDidMount() {
    BackHandler.addEventListener('hardwareBackPress', this.handleBackButton);
    
    axios.get(`https://classcast-198812.appspot.com/test_updated/view_attempted_test/`+this.props.navigation.state.params.test_id)
      .then((response)=>{
        console.log("sdjsadjkssddnsa: "+JSON.stringify(response.data));
        this.setState({ 
          blocks: response.data[0].blocks,
          sections: response.data[0].blocks.map(data => ({name: data.section_name, active_question_number: 0})),
          loading: true
        });
      })
      .catch((error)=> {
        console.log('sdjsadjkssddnsa'+error);
      });
  }

  _renderItem = ({item, index}) => (
      <TouchableNativeFeedback
         onPress={() => {
          this.setState({ 
            selectedSection: index,
            questionIndex: this.state.sections[index].active_question_number
           })
         }}
      >
        <View style={{height: 6 * vh, marginLeft: 5 *vw, marginRight: 5 * vw, alignItems: 'center', justifyContent: 'center'}}>
           <Text style={{fontFamily: 'Montserrat-Regular', fontSize: 3 * vw, color: this.state.selectedSection==index ? 'red': 'white'}}>{item.name}</Text>
        </View>
      </TouchableNativeFeedback>
  );

  _renderQuestionIndex =  ({item, index}) => (
      <TouchableNativeFeedback
         onPress={() => {
          this.setState({questionIndex: index});
          temp = this.state.sections;
          temp[this.state.selectedSection].active_question_number = index;
          this.setState({sections: temp});
         }}
      >
        <View style={{height: 6 * vw, width: 6 * vw, marginLeft: 5 *vw, marginTop: 2 * vh, marginRight: 4 * vw, alignItems: 'center', justifyContent: 'center', backgroundColor: '#323131', borderRadius: 3 * vw}}>
           <Text style={{fontFamily: 'Montserrat-Regular', fontSize: 3 * vw, color: this.state.sections[this.state.selectedSection].active_question_number==index ? 'red': 'white'}}>{index+1}</Text>
        </View>
      </TouchableNativeFeedback>
  );


  render () {
    if(!this.state.loading){
      return(
        <View style={styles.container}>
          <MaterialIndicator color='purple' />
        </View>
      )
    }
    else{
      return(
        <View style={styles.container}>
          <View style={styles.testHeader}>
            
            <View style={{flexDirection: 'column'}}>
              <Text style={styles.headerText}></Text>
              <Text style={styles.headerText}></Text>
            </View>
            <TouchableNativeFeedback
              onPress={() => {
                if(this.state.language == 'en')
                  this.setState({language: 'hn'})
                else
                  this.setState({language: 'en'})
              }}
            >
              <Image
                style={{height: 7.5 * vw, width: 7.5 * vw, marginLeft: 5 * vw}}
                source={{uri: this.state.language == 'en'? 'data:image/png;base64,'
                            : 'data:image/png;base64,'
                }}
              />
            </TouchableNativeFeedback>
            <TouchableNativeFeedback
              onPress={() => {
                this.setState({ showReviewModal: true })
              }}
            >
              <Image
                style={{height: 7 * vw, width: 7 * vw, marginLeft: 4 * vw}}
                source={{uri: 'data:image/png;base64,'}}
              />
            </TouchableNativeFeedback>
          </View>
          <View style={styles.sectionHeader}>
            <FlatList
              horizontal={true}
              showsHorizontalScrollIndicator={false}
              data={this.state.sections}
              renderItem={this._renderItem}
              extraData={this.state}
            />
          </View>
          <View style={{flexDirection: 'row'}}>
            <View style={styles.questionIndex}>
              { this.state.loading &&
                <FlatList
                  horizontal={true}
                  showsHorizontalScrollIndicator={false}
                  data={this.state.blocks[this.state.selectedSection].data}
                  renderItem={this._renderQuestionIndex}
                  extraData={this.state}
                />
              }
            </View>
            <TouchableNativeFeedback onPress={()=> this.setState({showSubmitModal: true})}>              
              <View style={{height: 5 * vh, width: '19%', backgroundColor: '#323131', alignSelf: 'center', justifyContent: 'center', borderRadius: 4 * vw, alignItems: 'center'}}>
                <Text style={{fontFamily: 'Montserrat-Regular', fontSize: 3 * vw, color: 'white'}}>End</Text>
              </View>
            </TouchableNativeFeedback>
          </View>
          { this.state.loading &&
            <Modal 
              isVisible={this.state.showSubmitModal}
              onRequestClose={() => {this.setState({showSubmitModal: false})}}>
              <View style={{height: 18 * vh, width: '70%', position: 'absolute', alignSelf: 'center', borderRadius: 2*vw, backgroundColor: 'white'}}>
                <View style={{height: 10 * vh, width: '100%', justifyContent: 'center'}}>
                  <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 4 * vw, marginLeft: 2 * vw, marginRight: 2 * vw, color: 'black'}}> Are you sure you want to finish the review? </Text>
                </View>
                <View style={{flexDirection: 'row', height: 8 * vh}}>
                  <TouchableNativeFeedback onPress={()=>this.props.navigation.goBack(null)}>
                    <View style={{height: 8 * vh, width: '50%', backgroundColor: '#323131', justifyContent: 'center', alignItems: 'center', borderBottomLeftRadius: 2 * vw}}>
                      <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 4 * vw, color: '#ffffff'}}> Yes </Text>
                    </View>
                  </TouchableNativeFeedback>
                  <TouchableNativeFeedback onPress={()=> this.setState({showSubmitModal: false})}>
                    <View style={{height: 8 * vh, width: '50%', backgroundColor: '#ffffff', justifyContent: 'center', alignItems: 'center', borderBottomRightRadius: 2 * vw}}>
                      <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 4 * vw}}> No </Text>
                    </View>
                  </TouchableNativeFeedback>
                </View>
              </View>
            </Modal>
          }
          { this.state.loading &&
            <Modal 
            isVisible={this.state.showReviewModal}
            onRequestClose={() => {
              this.setState({showReviewModal: false})
            }}
            >
              <View style={{ height: 60 * vh, width: 70 * vw, backgroundColor: 'white', position: 'absolute', alignSelf: 'center', borderRadius: 2*vw }}>
                
                <View style={{backgroundColor: '#323131', borderTopLeftRadius: 2 * vw, borderTopRightRadius: 2 * vw}}>
                  <FlatList
                    horizontal={true}
                    showsHorizontalScrollIndicator={false}
                    data={this.state.sections}
                    renderItem={this._renderItem}
                    extraData={this.state}
                  />
                </View>
                <ScrollView style={{width: '100%'}}>
                  <View style={{flexWrap: 'wrap', flexDirection: 'row', marginLeft: 5 * vw, marginRight: 5 * vw}}>
                    {
                    this.state.blocks[this.state.selectedSection].data && this.state.blocks[this.state.selectedSection].data.map((question, index)=>{
                      return(
                          <View style={{height: 10 * vw, width: 10 * vw, borderRadius: 5 * vw, margin: 5 * vw, alignItems: 'center', justifyContent: 'center', backgroundColor: question.attempted ? '#d267db': 'white', elevation: 5}}>
                            <Text style={{fontFamily: 'Montserrat-Regular', fontSize: 3 * vw}}>{index+1}</Text>
                          </View>
                        )
                    })
                    }
                  </View>
                </ScrollView>
                <TouchableNativeFeedback
                  onPress={()=>{
                     this.setState({
                      showReviewModal: false,
                      showSubmitModal: true})
                  }}
                >
                  <View style={{height: 8 * vh, width: '100%', backgroundColor: '#323131', justifyContent: 'center', alignItems: 'center', borderBottomLeftRadius: 2 * vw, borderBottomRightRadius: 2 * vw}}>
                    <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 5 * vw, color: 'white'}}>End Review</Text>
                  </View>
                </TouchableNativeFeedback>
              </View>
              <TouchableNativeFeedback onPress={() => this.setState({showReviewModal: false})}>  
                <Image
                  style={{height: 10 * vw, width: 10 * vw, position: 'absolute', bottom: 5 * vh, alignSelf: 'center'}}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </TouchableNativeFeedback>
            </Modal>
          }
          <ScrollView style={{width: '100%'}}>
            <View style={{height : 5 * vh, width: 50 * vw, marginLeft: 5 * vw, justifyContent: 'center', alignItems: 'center', flexDirection: 'row', backgroundColor: 'rgba(50,50,50,0.9)', borderRadius: 4 * vw, marginTop: 1 * vh}}>
              <Image
                style={{
                  width: 5 * vw,
                  height: 5 * vw,
                  resizeMode: 'contain',
                  marginRight: 2 * vw
                }}
                source={{uri: this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].attempted ? (this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].correctOption == this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].selectedOption) 
                  ? 'data:image/png;base64,'
                  : 'data:image/png;base64,' 
                  : 'data:image/png;base64,'}}
              />
              <Text style={[styles.rightSplitText], {fontSize: 3 * vh, color: '#ffffff' }}>{this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].attempted ? (this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].correctOption == this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].selectedOption)? 'Correct': 'Wrong' : 'Unattempted'}</Text>
            </View>
          { this.state.blocks[this.state.selectedSection].data[this.state.questionIndex][this.state.language].comp != "" &&
            <View style={styles.textContainer}>
              <RenderQuestions
                data={{text: "<strong>Passage</strong>"+"<p>"+this.state.blocks[this.state.selectedSection].data[this.state.questionIndex][this.state.language].comp.split('//storage.googleapis.com/classcast_exams_images/').join('https://storage.googleapis.com/classcast_exams_images/').split('https://console.cloud.google.com/storage/browser').join('https://storage.googleapis.com').split('\\\\').join('\\')+"</p>", color: 'white'}}
                />
            </View>
          }
            <View style={styles.textContainer}>
              <RenderQuestions
                data={{text: "<strong>Question</strong>"+"<p>"+this.state.blocks[this.state.selectedSection].data[this.state.questionIndex][this.state.language].value.split('//storage.googleapis.com/classcast_exams_images/').join('https://storage.googleapis.com/classcast_exams_images/').split('https://console.cloud.google.com/storage/browser').join('https://storage.googleapis.com').split('\\\\').join('\\')+"</p>", color: 'white'}}
                />
            </View>
            { 
              this.state.blocks[this.state.selectedSection].data[this.state.questionIndex][this.state.language].options && this.state.blocks[this.state.selectedSection].data[this.state.questionIndex][this.state.language].options.map((options, index)=>{
                return(
                    <View style={[styles.textContainer, {marginTop: 1 * vh}]}>
                      { this.state.loading &&
                      <RenderQuestions
                        data={{text: "<p>"+options.value.split('//storage.googleapis.com/classcast_exams_images/').join('https://storage.googleapis.com/classcast_exams_images/').split('https://console.cloud.google.com/storage/browser').join('https://storage.googleapis.com').split('\\\\').join('\\')+"</p>", color: this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].correctOption.split('//storage.googleapis.com/classcast_exams_images/').join('https://storage.googleapis.com/classcast_exams_images/').split('https://console.cloud.google.com/storage/browser').join('https://storage.googleapis.com').split('\\\\').join('\\') == (index+1).toString() ? '#80e180': (this.state.blocks[this.state.selectedSection].data[this.state.questionIndex].selectedOption == (index+1).toString() ? '#f28888': 'white' )}}
                        />
                      }
                    </View>

                )
              })
            }
            { this.state.blocks[this.state.selectedSection].data[this.state.questionIndex]['sol'][this.state.language].value != "" &&
              <View style={styles.textContainer}>
                <RenderQuestions
                  data={{text: "<strong>Solution</strong>"+"<p>"+this.state.blocks[this.state.selectedSection].data[this.state.questionIndex]['sol'][this.state.language].value.split('//storage.googleapis.com/classcast_exams_images/').join('https://storage.googleapis.com/classcast_exams_images/').split('https://console.cloud.google.com/storage/browser').join('https://storage.googleapis.com').split('\\\\').join('\\')+"</p>", color: 'white'}}
                  />
              </View>
            }
            <View style={{flexDirection: 'row', justifyContent: 'space-around', marginTop: 3 * vh}}>
              <TouchableNativeFeedback
                onPress={() => {
                  if(this.state.questionIndex != 0) {
                    temp = this.state.sections;
                    temp[this.state.selectedSection].active_question_number = this.state.questionIndex-1;
                    this.setState({sections: temp});
                    this.setState({questionIndex: this.state.questionIndex-1});
                  }
                 }}
              >
                <Image
                  style={{height: 10 * vw, width: 10 * vw}}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </TouchableNativeFeedback>

              <TouchableNativeFeedback
                onPress={() => {
                  if(this.state.questionIndex != this.state.blocks[this.state.selectedSection].data.length-1) {
                    temp = this.state.sections;
                    temp[this.state.selectedSection].active_question_number = this.state.questionIndex+1;
                    this.setState({sections: temp});
                    this.setState({questionIndex: this.state.questionIndex+1});
                  }
                  else {
                    if(this.state.sections.length > this.state.selectedSection+1) {
                      this.setState({ 
                        questionIndex: 0,
                        selectedSection: this.state.selectedSection+1
                       });
                    }
                    else {
                      this.setState({showSubmitModal: true});
                    }
                  }
                 }}
              >
                <Image
                  style={{height: 10 * vw, width: 10 * vw}}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </TouchableNativeFeedback>
            </View>
          </ScrollView>
          <TouchableNativeFeedback
            onPress={() => {
              this.props.navigation.dispatch(StackActions.popToTop());
              this.props.navigation.navigate('HomeStack', {}, NavigationActions.navigate({ routeName: 'Home' }))
            }}
              >
            <View style={[styles.nextButton, {backgroundColor: '#323131'}]}>
                <Text style={{fontFamily: 'Montserrat-SemiBold', fontSize: 4 * vw, color: 'white'}}>Back to main menu</Text>
            </View>
          </TouchableNativeFeedback>
        </View>
      )
    }
  }

}
export default viewTest

